void DFS(int money, vector<int>& prices, int index, int sum, vector<int>& path, vector<string>& res) {
    if (sum >= money) {
        // 找到一个可选方案
        if (sum == money) {
            string tmp = "[";
            for (int i = 0; i < path.size(); i++) {
                tmp += to_string(path[i]);
                tmp += ", ";
            }
            tmp.pop_back();
            tmp.pop_back();
            tmp += "]";
            res.push_back(tmp);
        }
        return;
    }
    // 递归回溯
    for (int i = index; i < prices.size(); i++) {
        path.push_back(prices[i]);
        DFS(money, prices, i, sum + prices[i], path, res);
        path.pop_back();
    }
}
