public class Main {
    static List<String> res = new ArrayList<>();
​
    // 递归枚举所有组合
    static void dfs(int money, List<Integer> prices, int index, int sum, List<Integer> path) {
        if (sum >= money) {
            if (sum == money) {
                res.add("[" + String.join(", ", path.stream().map(String::valueOf).toArray(String[]::new)) + "]");
            }
            return;
        }
        // 递归回溯
        for (int i = index; i < prices.size(); i++) {
            path.add(prices.get(i));
            dfs(money, prices, i, sum + prices.get(i), path);
            path.remove(path.size() - 1);
        }
    }
​
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int money = Integer.parseInt(sc.nextLine());
