        if (!line.isEmpty()) {
            for (String part : line.split(",")) {
                prices.add(Integer.parseInt(part.trim()));
            }
        }
​
        dfs(money, prices, 0, 0, new ArrayList<>());
        System.out.println(res.isEmpty() ? "[]" : "[" + String.join(", ", res) + "]");
