function dfs(money, prices, index, sum, path, res) {
    if (sum >= money) {
        if (sum === money) {
            res.push("[" + path.join(", ") + "]");
        }
        return;
    }
    for (let i = index; i < prices.length; i++) {
        path.push(prices[i]);
        dfs(money, prices, i, sum + prices[i], path, res);
        path.pop();
    }
}
