package main
​
import (
    "bufio"
    "fmt"
    "os"
    "strconv"
    "strings"
)
​
var res []string
​
// 回溯搜索所有方案
func dfs(money int, prices []int, index int, sum int, path []int) {
    if sum >= money {
        if sum == money {
            parts := make([]string, len(path))
            for i, v := range path {
                parts[i] = strconv.Itoa(v)
            }
            res = append(res, "["+strings.Join(parts, ", ")+"]")
        }
        return
    }
    for i := index; i < len(prices); i++ {
        path = append(path, prices[i])
        dfs(money, prices, i, sum+prices[i], path)
        path = path[:len(path)-1]
    }
}
​
func main() {
    scanner := bufio.NewScanner(os.Stdin)
    scanner.Scan()
    moneyStr := scanner.Text()
    money, _ := strconv.Atoi(moneyStr)
​
    scanner.Scan()
    line := strings.Trim(scanner.Text(), "[]")
    prices := []int{}
    if len(line) > 0 {
        for _, s := range strings.Split(line, ",") {
            n, _ := strconv.Atoi(strings.TrimSpace(s))
            prices = append(prices, n)
        }
    }
​
    dfs(money, prices, 0, 0, []int{})
    if len(res) == 0 {
        fmt.Println("[]")
    } else {
        fmt.Printf("[%s]\n", strings.Join(res, ", "))
    }
}
